269	     1	import * as fs from 'fs';
270	     2	import * as path from 'path';
271	     3	import { v4 as uuidv4 } from 'uuid';
272	     4	import { Document } from '../shared/types';
273	     5	import { PersistenceService } from './persistence-service';
274	     6	
275	     7	const DOCUMENTS_META = 'documents-meta.json';
276	     8	
277	     9	export class DocumentService {
278	    10	  private persistence: PersistenceService;
279	    11	
280	    12	  constructor(persistence: PersistenceService) {
281	    13	    this.persistence = persistence;
282	    14	  }
283	    15	
284	    16	  /** List all imported documents. */
285	    17	  listDocuments(): Document[] {
286	    18	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
287	    19	    return docs ?? [];
288	    20	  }
289	    21	
290	    22	  /** Import a file from the given path. */
291	    23	  importDocument(filePath: string): Document {
292	    24	    if (!fs.existsSync(filePath)) {
293	    25	      throw new Error(`File not found: ${filePath}`);
294	    26	    }
295	    27	
296	    28	    const filename = path.basename(filePath);
297	    29	    const content = fs.readFileSync(filePath, 'utf-8');
298	    30	    const stats = fs.statSync(filePath);
299	    31	
300	    32	    const doc: Document = {
301	    33	      id: uuidv4(),
302	    34	      title: filename.replace(/\.[^.]+$/, ''),
303	    35	      filename,
304	    36	      importedAt: new Date().toISOString(),
305	    37	      size: stats.size,
306	    38	      status: 'imported',
307	    39	    };
308	    40	
309	    41	    // Copy file to data directory
310	    42	    this.persistence.copyFileToDocuments(filePath, filename);
311	    43	
312	    44	    // Store content for indexing
313	    45	    this.persistence.writeText(`content/${doc.id}.txt`, content);
314	    46	
315	    47	    // Update metadata
316	    48	    const docs = this.listDocuments();
317	    49	    docs.push(doc);
318	    50	    this.persistence.writeJson(DOCUMENTS_META, docs);
319	    51	
320	    52	    return doc;
321	    53	  }
322	    54	
323	    55	  /** Get a single document by ID. */
324	    56	  getDocument(id: string): Document | null {
325	    57	    const docs = this.listDocuments();
326	    58	    return docs.find(d => d.id === id) ?? null;
327	    59	  }
328	    60	
329	    61	  /** Get the text content of a document. */
330	    62	  getDocumentContent(id: string): string | null {
331	    63	    return this.persistence.readText(`content/${id}.txt`);
332	    64	  }
333	    65	
334	    66	  /** Update a document's metadata. */
335	    67	  updateDocument(id: string, updates: Partial<Document>): Document | null {
336	    68	    const docs = this.listDocuments();
337	    69	    const index = docs.findIndex(d => d.id === id);
338	    70	    if (index === -1) return null;
339	    71	
340	    72	    docs[index] = { ...docs[index], ...updates };
341	    73	    this.persistence.writeJson(DOCUMENTS_META, docs);
342	    74	    return docs[index];
343	    75	  }
344	    76	
345	    77	  /** Delete a document by ID. */
346	    78	  deleteDocument(id: string): boolean {
347	    79	    const docs = this.listDocuments();
348	    80	    const doc = docs.find(d => d.id === id);
349	    81	    if (!doc) return false;
350	    82	
351	    83	    this.persistence.deleteFromDocuments(doc.filename);
352	    84	
353	    85	    const updated = docs.filter(d => d.id !== id);
354	    86	    this.persistence.writeJson(DOCUMENTS_META, updated);
355	    87	    return true;
356	    88	  }
