     1	import * as fs from 'fs';
     2	import * as path from 'path';
     3	import { v4 as uuidv4 } from 'uuid';
     4	import { Document } from '../shared/types';
     5	import { PersistenceService } from './persistence-service';
     6	
     7	const DOCUMENTS_META = 'documents-meta.json';
     8	
     9	export class DocumentService {
    10	  private persistence: PersistenceService;
    11	
    12	  constructor(persistence: PersistenceService) {
    13	    this.persistence = persistence;
    14	  }
    15	
    16	  /** List all imported documents. */
    17	  listDocuments(): Document[] {
    18	    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
    19	    return docs ?? [];
    20	  }
    21	
    22	  /** Import a file from the given path. */
    23	  importDocument(filePath: string): Document {
    24	    if (!fs.existsSync(filePath)) {
    25	      throw new Error(`File not found: ${filePath}`);
    26	    }
    27	
    28	    const filename = path.basename(filePath);
    29	    const content = fs.readFileSync(filePath, 'utf-8');
    30	    const stats = fs.statSync(filePath);
    31	
    32	    const doc: Document = {
    33	      id: uuidv4(),
    34	      title: filename.replace(/\.[^.]+$/, ''),
    35	      filename,
    36	      importedAt: new Date().toISOString(),
    37	      size: stats.size,
    38	      status: 'imported',
    39	    };
    40	
    41	    // Copy file to data directory
    42	    this.persistence.copyFileToDocuments(filePath, filename);
    43	
    44	    // Store content for indexing
    45	    this.persistence.writeText(`content/${doc.id}.txt`, content);
    46	
    47	    // Update metadata
    48	    const docs = this.listDocuments();
    49	    docs.push(doc);
    50	    this.persistence.writeJson(DOCUMENTS_META, docs);
    51	
    52	    return doc;
    53	  }
    54	
    55	  /** Get a single document by ID. */
    56	  getDocument(id: string): Document | null {
    57	    const docs = this.listDocuments();
    58	    return docs.find(d => d.id === id) ?? null;
    59	  }
    60	
    61	  /** Get the text content of a document. */
    62	  getDocumentContent(id: string): string | null {
    63	    return this.persistence.readText(`content/${id}.txt`);
    64	  }
    65	
    66	  /** Update a document's metadata. */
    67	  updateDocument(id: string, updates: Partial<Document>): Document | null {
    68	    const docs = this.listDocuments();
    69	    const index = docs.findIndex(d => d.id === id);
    70	    if (index === -1) return null;
    71	
    72	    docs[index] = { ...docs[index], ...updates };
    73	    this.persistence.writeJson(DOCUMENTS_META, docs);
    74	    return docs[index];
    75	  }
    76	
    77	  /** Delete a document by ID. */
    78	  deleteDocument(id: string): boolean {
    79	    const docs = this.listDocuments();
    80	    const doc = docs.find(d => d.id === id);
    81	    if (!doc) return false;
    82	
    83	    this.persistence.deleteFromDocuments(doc.filename);
    84	
    85	    const updated = docs.filter(d => d.id !== id);
    86	    this.persistence.writeJson(DOCUMENTS_META, updated);
    87	    return true;
    88	  }
    89	}
