     1	import * as fs from 'fs';
     2	import * as path from 'path';
     3	
     4	export class PersistenceService {
     5	  private dataDir: string;
     6	  private documentsDir: string;
     7	  private indexDir: string;
     8	
     9	  constructor(dataDir: string) {
    10	    this.dataDir = dataDir;
    11	    this.documentsDir = path.join(dataDir, 'documents');
    12	    this.indexDir = path.join(dataDir, 'index');
    13	    this.ensureDirectories();
    14	  }
    15	
    16	  private ensureDirectories() {
    17	    fs.mkdirSync(this.dataDir, { recursive: true });
    18	    fs.mkdirSync(this.documentsDir, { recursive: true });
    19	    fs.mkdirSync(this.indexDir, { recursive: true });
    20	  }
    21	
    22	  /** Read a JSON file, returning null if it doesn't exist. */
    23	  readJson<T>(relativePath: string): T | null {
    24	    const fullPath = path.join(this.dataDir, relativePath);
    25	    if (!fs.existsSync(fullPath)) return null;
    26	    return JSON.parse(fs.readFileSync(fullPath, 'utf-8'));
    27	  }
    28	
    29	  /** Write a JSON file atomically. */
    30	  writeJson<T>(relativePath: string, data: T): void {
    31	    const fullPath = path.join(this.dataDir, relativePath);
    32	    const dir = path.dirname(fullPath);
    33	    fs.mkdirSync(dir, { recursive: true });
    34	    fs.writeFileSync(fullPath, JSON.stringify(data, null, 2), 'utf-8');
    35	  }
    36	
    37	  /** Read a text file. */
    38	  readText(relativePath: string): string | null {
    39	    const fullPath = path.join(this.dataDir, relativePath);
    40	    if (!fs.existsSync(fullPath)) return null;
    41	    return fs.readFileSync(fullPath, 'utf-8');
    42	  }
    43	
    44	  /** Write a text file. */
    45	  writeText(relativePath: string, content: string): void {
    46	    const fullPath = path.join(this.dataDir, relativePath);
    47	    const dir = path.dirname(fullPath);
    48	    fs.mkdirSync(dir, { recursive: true });
    49	    fs.writeFileSync(fullPath, content, 'utf-8');
    50	  }
    51	
    52	  /** Copy a file into the documents directory. */
    53	  copyFileToDocuments(sourcePath: string, filename: string): string {
    54	    const destPath = path.join(this.documentsDir, filename);
    55	    fs.mkdirSync(this.documentsDir, { recursive: true });
    56	    fs.copyFileSync(sourcePath, destPath);
    57	    return destPath;
    58	  }
    59	
    60	  /** Delete a file from the documents directory. */
    61	  deleteFromDocuments(filename: string): void {
    62	    const filePath = path.join(this.documentsDir, filename);
    63	    if (fs.existsSync(filePath)) {
    64	      fs.unlinkSync(filePath);
    65	    }
    66	  }
    67	
    68	  /** List all files in a directory. */
    69	  listFiles(relativePath: string): string[] {
    70	    const fullPath = path.join(this.dataDir, relativePath);
    71	    if (!fs.existsSync(fullPath)) return [];
    72	    return fs.readdirSync(fullPath);
    73	  }
    74	
    75	  /** Check if a file exists. */
    76	  exists(relativePath: string): boolean {
    77	    return fs.existsSync(path.join(this.dataDir, relativePath));
    78	  }
    79	
    80	  /** Get the data directory path. */
    81	  getDataDir(): string {
    82	    return this.dataDir;
    83	  }
    84	
    85	  /** Get the documents directory path. */
    86	  getDocumentsDir(): string {
    87	    return this.documentsDir;
    88	  }
    89	
    90	  /** Get the index directory path. */
    91	  getIndexDir(): string {
    92	    return this.indexDir;
    93	  }
    94	}
