import { useState } from 'react';
import { MAX_IMPORT_SIZE_BYTES, SUPPORTED_EXTENSIONS } from '../../shared/types';

interface Props {
  /** Resolves when the import succeeds; rejects with a user-readable Error otherwise. */
  onImport: (filePath: string) => Promise<void>;
  onCancel?: () => void;
}

/** Client-side pre-check; DocumentService re-validates authoritatively in main. */
function validateFile(file: File): string | null {
  const dot = file.name.lastIndexOf('.');
  const ext = dot >= 0 ? file.name.slice(dot).toLowerCase() : '';
  if (!(SUPPORTED_EXTENSIONS as readonly string[]).includes(ext)) {
    return `Unsupported file type "${ext || '(none)'}". Supported: ${SUPPORTED_EXTENSIONS.join(', ')}`;
  }
  if (file.size > MAX_IMPORT_SIZE_BYTES) {
    return `File is too large (${(file.size / (1024 * 1024)).toFixed(1)} MB). Maximum size is 10 MB.`;
  }
  return null;
}

export function ImportPanel({ onImport, onCancel }: Props) {
  const [importing, setImporting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const input = e.currentTarget;
    const file = input.files?.[0];
    // Reset so selecting the same file again still fires onChange.
    input.value = '';
    if (!file) return;

    setError(null);
    const validationError = validateFile(file);
    if (validationError) {
      setError(validationError);
      return;
    }

    const filePath = window.knowledgeBase.documents.getFilePath(file);
    if (!filePath) {
      setError('Could not resolve the file location. Please pick a file from disk.');
      return;
    }

    setImporting(true);
    try {
      await onImport(filePath);
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setImporting(false);
    }
  };

  return (
    <div style={{
      padding: '20px',
      background: '#16213e',
      borderRadius: '6px',
      border: '1px dashed #0f3460',
      textAlign: 'center',
      color: '#888',
    }}>
      <div style={{ fontSize: '14px', marginBottom: '8px' }}>Import Documents</div>
      <div style={{ fontSize: '12px' }}>
        Choose a file to add to your knowledge base.
        <br />
        Supported: {SUPPORTED_EXTENSIONS.join(', ')} files up to 10 MB
      </div>
      <input
        type="file"
        accept={SUPPORTED_EXTENSIONS.join(',')}
        onChange={handleChange}
        disabled={importing}
        style={{ marginTop: '10px' }}
      />
      {importing && (
        <div style={{ marginTop: '10px', fontSize: '12px', color: '#a0a0c0' }}>Importing…</div>
      )}
      {error && (
        <div
          role="alert"
          style={{ marginTop: '10px', fontSize: '12px', color: '#d9534f' }}
        >
          {error}
        </div>
      )}
      {onCancel && (
        <div style={{ marginTop: '12px' }}>
          <button
            onClick={onCancel}
            disabled={importing}
            style={{
              padding: '4px 10px',
              background: 'transparent',
              color: '#a0a0c0',
              border: '1px solid #0f3460',
              borderRadius: '3px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Cancel
          </button>
        </div>
      )}
    </div>
  );
}

