  if (d.method === 'Runtime.consoleAPICalled') logs.push(d.params.args.map(a => a.value ?? a.description).join(' '));
  if (d.method === 'Runtime.exceptionThrown') logs.push('EXC ' + JSON.stringify(d.params.exceptionDetails.exception?.description));
};
const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true })).result;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const text = () => ev('document.body.innerText').then(r => r.result.value);
const clickText = (t) => ev(`[...document.querySelectorAll('button')].find(b=>b.textContent.trim()===${JSON.stringify(t)}).click()`);
async function pick(file) {
  const doc = await send('DOM.getDocument');
  const q = await send('DOM.querySelector', { nodeId: doc.result.root.nodeId, selector: 'input[type=file]' });
  await send('DOM.setFileInputFiles', { nodeId: q.result.nodeId, files: [`${fixtures}/${file}`] });
  await sleep(800);
}
ws.onopen = async () => {
  await send('Runtime.enable'); await send('DOM.enable');
  await sleep(500);
  console.log('bridge:', JSON.stringify((await ev('Object.keys(window.knowledgeBase?.documents ?? {})')).result.value));
  console.log('--- initial\n' + await text());
  await clickText('+ Import');
  await sleep(300);
  for (const f of ['bad.pdf', 'huge.txt']) { await pick(f); console.log(`--- after ${f}\n` + await text()); }
  await pick('design-notes.md');
  console.log('--- after design-notes.md\n' + await text());
  await clickText('+ Import'); await sleep(300);
  await pick('meeting-summary.txt');
  console.log('--- after meeting-summary.txt\n' + await text());
  // direct bridge call with missing file -> error must propagate
  console.log('missing:', JSON.stringify((await ev(`window.knowledgeBase.documents.import('/nope/x.md').then(()=>'ok',e=>e.message)`)).result.value));
  console.log('console logs:', JSON.stringify(logs));
  ws.close();
};
